begin;

insert into public.places (
  slug, name, kind, address, neighborhood, city, state, postal_code,
  lat, lng, geo_precision, geo_note, phone, website, instagram, tags,
  source_url, source_label, schedule_status, last_confirmed_at, notes
) values
('catedral-metropolitana', 'Catedral Metropolitana Sagrado Coração de Jesus', 'catedral', 'Travessa Pe. Eugênio Herter, 33', 'Centro', 'Londrina', 'PR', '86010-140', -23.31206, -51.15955, 'edificio', 'Ponto do edifício no OpenStreetMap. O endereço oficial da paróquia é a Travessa Pe. Eugênio Herter, 33; o mapa nomeia uma via adjacente.', '(43) 3324-5255', 'https://catedrallondrina.com.br/', 'https://www.instagram.com/catedrallondrina', array['Missa', 'Confissão']::text[], 'https://catedrallondrina.com.br/', 'Site da Catedral de Londrina', 'confirmado', '2026-11-25'::date, 'Confissões dentro da catedral, por ordem de chegada, sem agendamento. A missa de domingo às 10h30 é transmitida pela Rádio Alvorada e pelas redes da Catedral. WhatsApp da secretaria: (43) 99991-2368.'),
('coracao-de-maria', 'Paróquia Coração de Maria', 'paroquia', 'Avenida Higienópolis, 1073', 'Centro', 'Londrina', 'PR', '86020-080', -23.319495, -51.165737, 'edificio', null, '(43) 3324-1684', 'https://cordemaria.com.br/', null, array['Missa', 'Confissão', 'Adoração']::text[], 'https://cordemaria.com.br/horarios/', 'Página de horários da Paróquia Coração de Maria', 'confirmado', '2026-11-25'::date, 'As confissões são agendadas pelo telefone da secretaria, (43) 3324-1684. Não há grade de horários publicada para o confessionário.'),
('imaculada-conceicao', 'Paróquia Imaculada Conceição', 'paroquia', 'Rua Belo Horizonte, 805', 'Centro', 'Londrina', 'PR', '86020-350', -23.311355, -51.16646, 'edificio', null, '(43) 3323-9710', 'https://imaculadalondrina.com.br/', null, array['Missa', 'Confissão', 'Acessível']::text[], 'https://imaculadalondrina.com.br/', 'Site da Paróquia Imaculada Conceição', 'confirmado', '2026-11-25'::date, 'As missas são no templo da Rua Belo Horizonte, 805. A secretaria fica na Rua Tupi, 241, CEP 86020-350 — endereço que a Arquidiocese também publica. O site informa acolhida para idosos, gestantes e cadeirantes, e que não há estacionamento próprio. Horários de confissão não estão publicados: é preciso falar com a secretaria.'),
('sagrados-coracoes', 'Paróquia dos Sagrados Corações', 'paroquia', 'Rua Mato Grosso, 1167', 'Centro', 'Londrina', 'PR', '86010-180', -23.319444, -51.156167, 'edificio', null, '(43) 3329-7064', 'https://www.paroquiasagradoscoracoes.com.br/', null, array['Missa', 'Confissão', 'Adoração']::text[], 'https://www.paroquiasagradoscoracoes.com.br/horarios-de-missas/', 'Página de horários da Paróquia dos Sagrados Corações', 'parcial', null, 'Estes horários estavam publicados na página de horários da paróquia. Em 25/11/2026 o domínio não respondeu a uma nova consulta, então a grade fica como parcial. Telefone da Arquidiocese: (43) 3329-7064. A página de horários também cita o WhatsApp (43) 99928-5247. Confirme antes de ir.'),
('rainha-dos-apostolos', 'Paróquia Nossa Senhora Rainha dos Apóstolos', 'paroquia', 'Avenida Tiradentes, 43', 'Jardim Shangri-lá', 'Londrina', 'PR', '86070-000', -23.302728, -51.17355, 'edificio', null, '(43) 3327-2518', 'https://rainhadosapostolos.com.br/', null, array['Missa', 'Confissão', 'Adoração']::text[], 'https://rainhadosapostolos.com.br/', 'Site da Paróquia Nossa Senhora Rainha dos Apóstolos', 'confirmado', '2026-11-25'::date, 'A missa de domingo às 16h é em latim, no Novus Ordo. Na primeira quinta-feira do mês há Dia da Palavra às 20h (encontro, não listado como missa). Em solenidades os horários podem mudar. Para confissão fora da sexta-feira, a paróquia pede contato com a secretaria.'),
('rainha-do-universo', 'Paróquia Nossa Senhora Rainha do Universo', 'paroquia', 'Rua Ibirá, 99', 'Parque Alvorada', 'Londrina', 'PR', '86062-430', -23.306072, -51.188094, 'edificio', 'O ponto é o edifício religioso no OpenStreetMap, associado à Rua Ituiutaba, no mesmo quarteirão do endereço publicado (Rua Ibirá, 99).', '(43) 3327-0427', 'https://rainhadouniverso.com.br/', null, array['Missa']::text[], 'https://rainhadouniverso.com.br/horarios/', 'Página de horários da Paróquia Rainha do Universo', 'confirmado', '2026-11-25'::date, 'Terça-feira às 19h a paróquia publica celebração da Palavra, não missa, e por isso ela não entra na grade. Há missa de domingo às 8h30 numa capela cujo endereço não está na página de horários; ela não foi colocada neste ponto para não indicar o lugar errado. Em festas e solenidades os horários podem mudar.'),
('sao-vicente-de-paulo', 'Paróquia São Vicente de Paulo', 'paroquia', 'Avenida Madre Leônia Milito, 545', 'Guanabara', 'Londrina', 'PR', '86050-270', -23.334893, -51.169316, 'via', 'O OpenStreetMap não interpola o número 545. O ponto é o trecho da Avenida Madre Leônia Milito no Guanabara. Use Como chegar com o endereço completo.', '(43) 3339-0252', 'https://saovicentelondrina.com.br/', 'https://www.instagram.com/saovicentelondrina', array['Missa', 'Confissão', 'Estacionamento']::text[], 'https://saovicentelondrina.com.br/horarios-de-missas/', 'Página de horários da Paróquia São Vicente de Paulo', 'confirmado', '2026-11-25'::date, 'A missa de domingo às 10h é transmitida online. Confissões existem, mas o horário é por agendamento com o pároco, pela secretaria — não há grade publicada. A página da Arquidiocese descreve estacionamento no térreo do centro pastoral.'),
('santana', 'Paróquia Sant''Ana', 'paroquia', 'Rua Ruy Ferraz de Carvalho, 280', 'Terras de Santana II', 'Londrina', 'PR', null, -23.349073, -51.194097, 'via', 'O número 280 não está interpolado no OpenStreetMap. O ponto é a Avenida Ruy Ferraz de Carvalho. O site da paróquia usa Rua e Avenida para o mesmo endereço. Use Como chegar.', '(43) 3326-2749', 'https://paroquiasantanalondrina.org/', 'https://www.instagram.com/paroquiasantanalondrina', array['Missa']::text[], 'https://paroquiasantanalondrina.org/santa-missa/', 'Página de missas da Paróquia Sant''Ana', 'confirmado', '2026-11-25'::date, 'Grade da matriz. A paróquia também publica missas em capelas, algumas só em certas semanas do mês. A de domingo às 11h30 tem transmissão online. WhatsApp citado no site: (43) 98478-1305.'),
('mae-da-divina-providencia', 'Paróquia Mãe da Divina Providência', 'paroquia', 'Rua José Nogueira Franco, 435', 'Parque Residencial Alcântara', 'Londrina', 'PR', '86047-420', -23.346456, -51.167199, 'via', 'O número 435 não está interpolado. O ponto é a Rua José Nogueira Franco. O CEP publicado pela paróquia é 86047-420.', '(43) 3341-5226', 'https://mdprovidencia.com.br/', null, array['Missa', 'Adoração']::text[], 'https://mdprovidencia.com.br/noticias/horario-de-missa', 'Notícia de horários da Paróquia Mãe da Divina Providência', 'parcial', '2026-11-25'::date, 'A notícia de 7/10/2026 lista sábado às 18h. O rodapé do mesmo site acrescenta, no primeiro sábado, terço e adoração às 9h e missa às 10h, e na primeira sexta a novena junto da missa das 19h. As duas informações estão no site; por isso a ficha é parcial. WhatsApp pastoral: (43) 99992-1434.'),
('santa-rita-de-cassia', 'Santuário Santa Rita de Cássia', 'santuario', 'Rua Pedro Abelardo, 70', 'Jardim Califórnia', 'Londrina', 'PR', '86040-070', -23.334224, -51.142334, 'via', 'O número 70 não está interpolado. O ponto é a Rua Pedro Abelardo, no Jardim Califórnia.', '(43) 3336-3166', 'https://santaritalondrina.com.br/', null, array['Missa']::text[], 'https://santaritalondrina.com.br/paroquias', 'Site do Santuário Santa Rita de Cássia', 'confirmado', '2026-11-25'::date, 'Também é paróquia do Decanato Leste. No dia 22, o site publica horários adicionais (6h, 12h, 15h e 19h30 de segunda a sexta; 6h, 12h, 15h e 19h no sábado). Esses horários de um dia do mês não entram na grade semanal. Linha de ônibus citada pelo santuário: 201.'),
('nossa-senhora-auxiliadora', 'Paróquia Nossa Senhora Auxiliadora', 'paroquia', 'Rua Dom Bosco, 55', 'Jardim Dom Bosco', 'Londrina', 'PR', '86060-340', -23.311451, -51.177207, 'edificio', null, '(43) 3327-3529', 'https://auxiliadoraonline.com.br/', null, array['Missa']::text[], 'https://auxiliadoraonline.com.br/', 'Site da Paróquia Nossa Senhora Auxiliadora', 'confirmado', '2026-11-25'::date, 'A missa de domingo às 18h30 é transmitida. Intenções de missa, de segunda a sexta, até 17h, e no fim de semana até 11h de sábado, pelo telefone (43) 99992-3529.'),
('sao-jose-operario', 'Paróquia São José Operário', 'paroquia', 'Rua Ruy Virmond Carnascialli, 486', 'Jardim Leonor', 'Londrina', 'PR', '86071-260', -23.290712, -51.19717, 'via', 'O número não está interpolado, mas o trecho encontrado usa o mesmo CEP publicado pela paróquia, 86071-260.', '(43) 3338-5333', 'https://saojoselondrina.com.br/', null, array['Missa']::text[], 'https://saojoselondrina.com.br/', 'Site da Paróquia São José Operário', 'confirmado', '2026-11-25'::date, 'WhatsApp publicado no site: (43) 98808-4825. O site também cita a Capela da Reconciliação, sem grade de horários.'),
('cristo-bom-pastor', 'Paróquia Cristo Bom Pastor', 'paroquia', 'Rua Nova Esperança, 222', 'Conjunto Lindóia', 'Londrina', 'PR', '86031-140', -23.28441, -51.123707, 'via', 'O número 222 não está interpolado. O ponto é a Rua Nova Esperança, no Conjunto Habitacional Lindóia.', '(43) 3337-7595', 'https://paroquiacristobompastor.com.br/', null, array['Missa', 'Adoração']::text[], 'https://paroquiacristobompastor.com.br/p/atividades-permanentes', 'Atividades permanentes da Paróquia Cristo Bom Pastor', 'confirmado', '2026-11-25'::date, 'Grade só da matriz, no Lindóia. As comunidades da paróquia têm missas próprias, publicadas na mesma página. A adoração na matriz é na primeira sexta-feira, às 20h.'),
('capela-sao-cristovao', 'Capela São Cristóvão', 'capela', 'Avenida José Rodrigues Martins, 373', 'Conjunto Mister Thomas', 'Londrina', 'PR', '86031-530', -23.280524, -51.128638, 'via', 'O número 373 não está interpolado. O ponto é a avenida no Conjunto Habitacional Mister Thomas.', '(43) 3337-7595', 'https://paroquiacristobompastor.com.br/p/atividades-permanentes', null, array['Missa']::text[], 'https://paroquiacristobompastor.com.br/p/atividades-permanentes', 'Atividades permanentes da Paróquia Cristo Bom Pastor', 'confirmado', '2026-11-25'::date, 'Comunidade da Paróquia Cristo Bom Pastor. A página também indica adoração na segunda quinta-feira do mês, após a missa das 20h, sem um horário de início separado.'),
('nipo-brasileira', 'Paróquia Pessoal Nipo-Brasileira Imaculada Conceição', 'paroquia', 'Rua Belo Horizonte, 795', 'Centro', 'Londrina', 'PR', '86020-060', -23.311171, -51.166559, 'edificio', null, '(43) 3322-1526', 'https://www.imaculadanipo.com.br/', null, array['Missa']::text[], 'https://www.imaculadanipo.com.br/missas', 'Página de missas da Paróquia Nipo-Brasileira', 'parcial', '2026-11-25'::date, 'O site da paróquia publica a missa de domingo às 8h30. Não há grade de dias de semana nessa página. A missa de domingo fica registrada; o restante está a confirmar com a secretaria, (43) 3322-1526.'),
('nossa-senhora-das-gracas', 'Paróquia Nossa Senhora das Graças', 'paroquia', 'Rua Luiz Dias, 393', 'Vila Brasil', 'Londrina', 'PR', '86015-440', -23.328698, -51.154702, 'edificio', 'Edifício religioso no OpenStreetMap, na Rua Luiz Dias. A Arquidiocese indica o bairro Vila Brasil.', '(43) 3342-1276', null, null, array['Missa']::text[], 'https://arquidioceselondrina.com.br/paroquias/parquia-nossa-senhora-das-graas', 'Ficha da Arquidiocese de Londrina', 'a_confirmar', null, 'Endereço e telefone vêm da Arquidiocese. Diretórios de horários divergem entre si e não foram copiados. A grade de missas, confissões e adoração está a confirmar com a secretaria.'),
('cristo-redentor', 'Paróquia Cristo Redentor', 'paroquia', 'Rua Braga, 99', 'Jardim Piza', 'Londrina', 'PR', '86041-040', -23.349014, -51.142192, 'edificio', 'O ponto é o edifício religioso no OpenStreetMap, na esquina com a Avenida Paris, a poucos metros do endereço oficial da Arquidiocese (Rua Braga, 99).', '(43) 3341-5999', null, null, array['Missa']::text[], 'https://arquidioceselondrina.com.br/paroquias', 'Diretório de paróquias da Arquidiocese de Londrina', 'a_confirmar', null, 'Endereço e telefone vêm da Arquidiocese. Há posts de redes sociais com horários, mas o número da rua nesses posts (108) não coincide com o da Arquidiocese (99). A grade não foi copiada e está a confirmar.'),
('santa-terezinha', 'Paróquia Santa Terezinha do Menino Jesus', 'paroquia', 'Avenida Saul Elkind, 5465', 'Jardim Ilha do Mel', 'Londrina', 'PR', '86082-000', -23.261161, -51.188609, 'edificio', null, '(43) 3338-6585', null, null, array['Missa']::text[], 'https://portalcdicbr.cnbb.org.br/igreja/d2188ffe-5fe4-4896-8153-1476e194a9c8', 'Portal de consultas da CNBB (CDICBR)', 'a_confirmar', null, 'Endereço e telefone vêm do cadastro da CNBB. Uma compilação de 2023 e um diretório de terceiros não coincidem na grade semanal. Os horários ficam a confirmar com a secretaria. A CNBB vincula a Capela Nossa Senhora de Guadalupe a esta paróquia, sem endereço publicado nessa ficha.'),
('nossa-senhora-de-fatima', 'Paróquia Nossa Senhora de Fátima', 'paroquia', 'Avenida Dez de Dezembro, 647', 'Vila Casoni', 'Londrina', 'PR', '86026-220', -23.298893, -51.144983, 'edificio', null, '(43) 3325-1842', null, null, array['Missa']::text[], 'https://divisaodaigreja.com/paroquia-nossa-senhora-de-fatima-vila-casoni/', 'Cadastro eclesiástico com o endereço da paróquia', 'a_confirmar', null, 'Endereço e telefone conferidos no cadastro da circunscrição. Horários que aparecem só em diretórios de terceiros não foram copiados. A grade está a confirmar com a secretaria.'),
('nossa-senhora-de-nazare', 'Paróquia Nossa Senhora de Nazaré', 'paroquia', 'Rua Aurélio Buarque de Holanda, 456', 'Parigot de Souza', 'Londrina', 'PR', null, -23.267014, -51.177024, 'via', 'O número 456 não está interpolado. O ponto é a Rua Aurélio Buarque de Holanda. O bairro exibido é o do OpenStreetMap.', '(43) 3328-3666', 'https://paroquianazare.com.br/', null, array['Missa']::text[], 'https://paroquianazare.com.br/', 'Site da Paróquia Nossa Senhora de Nazaré', 'a_confirmar', null, 'O site publica endereço, telefone e uma agenda que mistura a matriz com as capelas São José de Anchieta e Santa Rosa de Lima. A grade semanal da matriz não ficou inequívoca na leitura do texto, então os horários permanecem a confirmar em vez de serem estimados.')
on conflict (slug) do update set
  name = excluded.name,
  kind = excluded.kind,
  address = excluded.address,
  neighborhood = excluded.neighborhood,
  city = excluded.city,
  state = excluded.state,
  postal_code = excluded.postal_code,
  lat = excluded.lat,
  lng = excluded.lng,
  geo_precision = excluded.geo_precision,
  geo_note = excluded.geo_note,
  phone = excluded.phone,
  website = excluded.website,
  instagram = excluded.instagram,
  tags = excluded.tags,
  source_url = excluded.source_url,
  source_label = excluded.source_label,
  schedule_status = excluded.schedule_status,
  last_confirmed_at = excluded.last_confirmed_at,
  notes = excluded.notes;

delete from public.schedules
where place_id in (select id from public.places where slug in ('catedral-metropolitana', 'coracao-de-maria', 'imaculada-conceicao', 'sagrados-coracoes', 'rainha-dos-apostolos', 'rainha-do-universo', 'sao-vicente-de-paulo', 'santana', 'mae-da-divina-providencia', 'santa-rita-de-cassia', 'nossa-senhora-auxiliadora', 'sao-jose-operario', 'cristo-bom-pastor', 'capela-sao-cristovao', 'nipo-brasileira', 'nossa-senhora-das-gracas', 'cristo-redentor', 'santa-terezinha', 'nossa-senhora-de-fatima', 'nossa-senhora-de-nazare'));

